/** Separates the dates of a `selectionMode: 'multiple'` value. */
const MULTIPLE_DATE_SEPARATOR = ',';

/** Separates the two ends of a `selectionMode: 'range'` value. Either side may be empty, so a
    half-picked range still round-trips rather than being discarded. */
const DATE_RANGE_SEPARATOR = '/';

/**
 * Which renderer draws which `fieldType`.
 *
 * All nine kinds, across nineteen wire types. `media` still draws a placeholder that edits
 * nothing — see `mediaFieldRenderer`. An unregistered type is not an error: {@link FieldInputComponent} falls back to a
 * plain textarea, exactly as it does in the admin today — but note that the fallback is a
 * *textarea*, so a consumer resolving a control through `resolveFieldControl` gets a free-text box
 * for an unregistered type rather than merely an unformatted reading of the value.
 *
 * Note what is absent compared with the admin's copy: `editor`. Config editors are authoring UI
 * and stay in that app — see the note in `field-renderer-contract.ts`.
 *
 * Keyed by {@link FieldDefinitionType} rather than `string`, so a key that is not a real field type
 * fails to compile — the drift this package exists to prevent, caught at the registration site.
 * `Partial` because the page-widget types are deliberately never registered here: nothing in this
 * package can draw one.
 *
 * Several types deliberately share one renderer, differing only in the config seeded below —
 * `Text` with the retired `Email`/`Url`/`Phone`, `Number`/`Decimal`, and `DatePicker` with the
 * two retired date types at the end of the map. See `FieldRendererKind`.
 */
export const FIELD_DEFINITION_TYPE_RENDERERS: Partial<
  Record<FieldDefinitionType, ErasedFieldRendererDescriptor>
> = {
  Text: textFieldRenderer(),
  Number: numberFieldRenderer({ maxFractionDigits: 0, step: 1 }),
  Decimal: numberFieldRenderer({ minFractionDigits: 2, maxFractionDigits: 2, step: 0.01 }),
  Currency: currencyFieldRenderer(),
  TextArea: textareaFieldRenderer(),
  Checkbox: checkboxFieldRenderer(),
  DatePicker: dateFieldRenderer(),
  RadioButton: radioFieldRenderer(),
  Dropdown: selectFieldRenderer(),
  Media: mediaFieldRenderer(),

  // Retired from the dropdown, kept readable here. Each was replaced by a type above that does
  // the same job — `Date`/`DateTime` by `DatePicker`, `Select` by `RadioButton`, `MultiSelect` by
  // `CheckboxGroup`, `Email`, `Url` and `Phone` by `Text`. These are not aliases for convenience:
  // a saved field's type can never be changed (`fieldType` is disabled on edit), so without them
  // every field already in an account of one of these types would fall through to the raw-JSON
  // textarea for good. `DateTime` keeps its old seed so such a field still opens with time switched on.
  //
  // `Select` stays pointed at the radio renderer even now that `Dropdown` exists: repointing it
  // would change what every field already saved as a `Select` draws, which is the one thing
  // keeping these entries is meant to prevent. `Dropdown` is where a new field of that shape goes.
  Date: dateFieldRenderer(),
  DateTime: dateFieldRenderer({ showTime: true, hourFormat: '12' }),
  Select: radioFieldRenderer(),
  Boolean: checkboxFieldRenderer({ checkboxType: 'single' }),
  MultiSelect: checkboxFieldRenderer({ checkboxType: 'group' }),
  CheckboxGroup: checkboxFieldRenderer({ checkboxType: 'group' }),
  Email: textFieldRenderer({ inputType: 'email', placeholder: 'name@example.com' }),
  // Each keeps its seed, so a saved field still opens as the input it always was.
  Url: textFieldRenderer({ inputType: 'url', placeholder: 'https://' }),
  Phone: textFieldRenderer({ inputType: 'tel' }),
};

/**
 * The descriptor for `fieldType`, or null for a type with no renderer.
 *
 * `Object.hasOwn` rather than a truthiness check, so a field type spelled `constructor` or
 * `toString` cannot borrow a prototype member and be mistaken for a registration.
 */
export function findFieldRenderer(fieldType: string): ErasedFieldRendererDescriptor | null {
  // `fieldType` stays a plain `string`: it arrives as free-form API data, and narrowing the
  // parameter would push the unchecked cast out to every caller instead of containing it here,
  // where `Object.hasOwn` is the check that makes it true.
  return Object.hasOwn(FIELD_DEFINITION_TYPE_RENDERERS, fieldType)
    ? (FIELD_DEFINITION_TYPE_RENDERERS[fieldType as FieldDefinitionType] ?? null)
    : null;
}

/** Whether `fieldType` has a typed renderer. */
export function isFieldRendererRegistered(fieldType: string): boolean {
  return findFieldRenderer(fieldType) !== null;
}

/**
 * Whether a field's value is a web address — what decides drawing it as a link.
 *
 * Read off the config, not the field type: a `Text` field with Input Type URL and a retired `Url`
 * field (whose seed sets the same input type) are the same control, and a `Url` field whose input
 * type was switched to something else no longer holds an address.
 */
export function isUrlField(fieldType: string, fieldConfig: string | null): boolean {
  const descriptor = findFieldRenderer(fieldType);

  if (descriptor?.kind !== 'text') {
    return false;
  }

  return (descriptor.parse(fieldConfig) as TextFieldConfig).inputType === 'url';
}

/**
 * A stored value as it should be *read* — the string to show where a control is not being drawn,
 * and the `valueFormatted` to send beside `value` on a save.
 *
 * The one entry point for this: resolving a descriptor, parsing its config and reaching for an
 * optional member is plumbing no consumer should repeat, and a consumer that got any step wrong
 * would quietly show raw values instead.
 *
 * Answers with `raw` untouched whenever there is nothing to apply — an unregistered field type, or
 * one of the descriptors that deliberately declares no `format` because what it stores is already
 * what it shows. That fallback is the whole error strategy: this never throws and never blanks a
 * value it cannot read, matching the rule the codecs are written to.
 */
export function formatFieldValue(
  fieldType: string,
  raw: string,
  fieldConfig: string | null,
): string {
  const descriptor = findFieldRenderer(fieldType);

  if (descriptor?.format === undefined) {
    return raw;
  }

  return descriptor.format(raw, descriptor.parse(fieldConfig));
}

/**
 * One factory per kind.
 *
 * `overrides` is what makes `Email` a text renderer with an email keyboard rather than a fourth
 * component. It is merged into the kind's defaults *before* `parse` closes over the result, so a
 * saved config missing a member falls back to **this field type's** default and not the kind's.
 *
 * Exported on purpose: this is the package's extension seam. A consumer adds a field type by
 * calling one of these with different seed config, with no new component and no package release.
 */
export function textFieldRenderer(
  overrides: Partial<TextFieldConfig> = {},
): ErasedFieldRendererDescriptor {
  const defaultConfig: TextFieldConfig = { ...DEFAULT_TEXT_FIELD_CONFIG, ...overrides };

  return eraseFieldRenderer<'text'>({
    kind: 'text',
    renderer: TextFieldInputComponent,
    defaultConfig,
    parse: (json) => parseTextFieldConfig(json, defaultConfig),
    // Identity both ways: the in-memory value and the wire value are the same string. No trim —
    // a trailing space can be meaningful in content, and normalising one away here would rewrite
    // a value the user did not touch.
    serialize: (value) => value,
    deserialize: (raw) => raw,
  });
}

export function textareaFieldRenderer(
  overrides: Partial<TextareaFieldConfig> = {},
): ErasedFieldRendererDescriptor {
  const defaultConfig: TextareaFieldConfig = { ...DEFAULT_TEXTAREA_FIELD_CONFIG, ...overrides };

  return eraseFieldRenderer<'textarea'>({
    kind: 'textarea',
    renderer: TextareaFieldInputComponent,
    defaultConfig,
    parse: (json) => parseTextareaFieldConfig(json, defaultConfig),
    // Identity both ways, exactly like `text` — see `textFieldRenderer` for why no trim.
    serialize: (value) => value,
    deserialize: (raw) => raw,
    // Only a `wysiwyg` field needs reading: its value is HTML, and a grid cell or `valueFormatted`
    // wants the words, not the tags. A plain textarea already stores what it shows.
    format: (raw, config) => (config.wysiwyg ? richTextToPlainText(raw) : raw),
  });
}

export function numberFieldRenderer(
  overrides: Partial<NumberFieldConfig> = {},
): ErasedFieldRendererDescriptor {
  const defaultConfig: NumberFieldConfig = { ...DEFAULT_NUMBER_FIELD_CONFIG, ...overrides };

  return eraseFieldRenderer<'number'>({
    kind: 'number',
    renderer: NumberFieldInputComponent,
    defaultConfig,
    parse: (json) => parseNumberFieldConfig(json, defaultConfig),
    // Config-independent on purpose: grouping, prefix and fraction digits are all display
    // settings, so the stored value stays plain digits and a config change never needs the data
    // rewritten. See `formatPlainNumber`.
    serialize: (value) => formatPlainNumber(value),
    deserialize: (raw) => parseFiniteNumber(raw),
    // Those same display settings, applied for reading only. The stored value is untouched — this
    // is what `valueFormatted` carries beside it.
    format: (raw, config) =>
      formatDecimal(raw, config.locale, {
        useGrouping: config.useGrouping,
        minFractionDigits: config.minFractionDigits,
        maxFractionDigits: config.maxFractionDigits,
        prefix: config.prefix,
        suffix: config.suffix,
      }),
  });
}

export function currencyFieldRenderer(
  overrides: Partial<CurrencyFieldConfig> = {},
): ErasedFieldRendererDescriptor {
  const defaultConfig: CurrencyFieldConfig = { ...DEFAULT_CURRENCY_FIELD_CONFIG, ...overrides };

  return eraseFieldRenderer<'currency'>({
    kind: 'currency',
    renderer: CurrencyFieldInputComponent,
    defaultConfig,
    parse: (json) => parseCurrencyFieldConfig(json, defaultConfig),
    // The amount only — the ISO code lives in the config, so the same stored `1234.5` renders as
    // `$1,234.50` or `€1.234,50` when the config changes, and stays arithmetic-ready for the
    // backend. Identical to the number codec on purpose.
    serialize: (value) => formatPlainNumber(value),
    deserialize: (raw) => parseFiniteNumber(raw),
    // The rendered amount, ISO code and all — `$1,234.50` for the `1234.5` stored above.
    format: (raw, config) =>
      formatDecimal(raw, config.locale, {
        useGrouping: config.useGrouping,
        minFractionDigits: config.minFractionDigits,
        maxFractionDigits: config.maxFractionDigits,
        currency: config.currency,
        currencyDisplay: config.currencyDisplay,
      }),
  });
}

export function checkboxFieldRenderer(
  overrides: Partial<CheckboxFieldConfig> = {},
): ErasedFieldRendererDescriptor {
  const defaultConfig: CheckboxFieldConfig = { ...DEFAULT_CHECKBOX_FIELD_CONFIG, ...overrides };

  return eraseFieldRenderer<'checkbox'>({
    kind: 'checkbox',
    renderer: CheckboxFieldInputComponent,
    defaultConfig,
    parse: (json) => parseCheckboxFieldConfig(json, defaultConfig),
    // The one codec here that branches on its config rather than merely reading a format from it:
    // `Checkbox` is a single field type covering two controls, so `checkboxType` decides whether a
    // value is a tri-state boolean or a list of ticked values. See `CheckboxFieldValue`.
    serialize: (value, config) => {
      if (config.checkboxType === 'group') {
        return Array.isArray(value) ? value.join(CHECKBOX_VALUE_SEPARATOR) : '';
      }

      if (typeof value !== 'boolean') {
        return '';
      }

      return value ? config.trueText : config.falseText;
    },
    deserialize: (raw, config) => {
      if (config.checkboxType === 'group') {
        const stored = new Set(
          raw
            .split(CHECKBOX_VALUE_SEPARATOR)
            .map((part) => part.trim())
            .filter((part) => part !== ''),
        );

        // Ordered by the config rather than by the stored string, so the boxes read top to bottom
        // however the value was written. An option since removed is dropped, which
        // `FieldInputComponent` then reports as unreadable rather than silently rewriting.
        return config.options.map((option) => option.value).filter((value) => stored.has(value));
      }

      const parsed = parseLooseBoolean(raw, config.trueText, config.falseText);

      // A binary box has no third state to show, so an unreadable value has to land somewhere;
      // false is the only honest choice, and `FieldInputComponent` flags it as unreadable so the
      // stored text survives untouched. A tri-state box keeps the null.
      if (parsed === null && !config.triState && raw.trim() !== '') {
        return false;
      }

      return parsed;
    },
    // Only the group mode maps. A single box already *stores* `trueText`/`falseText` — see the
    // serialize above — so its stored value is its display form and mapping again would be a
    // no-op at best.
    format: (raw, config) =>
      config.checkboxType === 'group'
        ? choiceLabels(raw, config.options, CHECKBOX_VALUE_SEPARATOR)
        : raw,
  });
}

export function radioFieldRenderer(
  overrides: Partial<RadioFieldConfig> = {},
): ErasedFieldRendererDescriptor {
  const defaultConfig: RadioFieldConfig = { ...DEFAULT_RADIO_FIELD_CONFIG, ...overrides };

  return eraseFieldRenderer<'radio'>({
    kind: 'radio',
    renderer: RadioFieldInputComponent,
    defaultConfig,
    parse: (json) => parseRadioFieldConfig(json, defaultConfig),
    serialize: (value) => value ?? '',
    // Only a value the field still offers is accepted. A stored option that has since been
    // removed comes back as null, which `FieldInputComponent` reports as unreadable rather than
    // silently clearing — the old value stays stored until someone picks a new one.
    deserialize: (raw, config) => {
      const value = raw.trim();

      return config.options.some((option) => option.value === value) ? value : null;
    },
    format: (raw, config) => choiceLabel(raw, config.options),
  });
}

export function selectFieldRenderer(
  overrides: Partial<SelectFieldConfig> = {},
): ErasedFieldRendererDescriptor {
  const defaultConfig: SelectFieldConfig = { ...DEFAULT_SELECT_FIELD_CONFIG, ...overrides };

  return eraseFieldRenderer<'select'>({
    kind: 'select',
    renderer: SelectFieldInputComponent,
    defaultConfig,
    parse: (json) => parseSelectFieldConfig(json, defaultConfig),
    // The second codec here that branches on its config rather than merely reading a format from
    // it, for the same reason the checkbox one does: `Dropdown` is a single field type covering
    // two controls, so `selectionMode` decides whether a value is one option or a list of them.
    // See `SelectFieldValue`.
    serialize: (value, config) => {
      if (config.selectionMode === 'multiple') {
        return Array.isArray(value) ? value.join(SELECT_VALUE_SEPARATOR) : '';
      }

      return typeof value === 'string' ? value : '';
    },
    // Only values the field still offers are accepted, in either mode. A stored option that has
    // since been removed is dropped, which `FieldInputComponent` then reports as unreadable rather
    // than silently rewriting — the old value stays stored until someone picks a new one.
    deserialize: (raw, config): SelectFieldValue => {
      if (config.selectionMode === 'multiple') {
        const stored = new Set(
          raw
            .split(SELECT_VALUE_SEPARATOR)
            .map((part) => part.trim())
            .filter((part) => part !== ''),
        );

        // Ordered by the config rather than by the stored string, so the picks read in the
        // authored order however the value was written. Round-trip stability survives that
        // reordering because the requirement is on this pair's *own* output:
        // `serialize(deserialize(serialize(v)))` is already in config order by the second pass.
        return config.options.map((option) => option.value).filter((value) => stored.has(value));
      }

      const value = raw.trim();

      return config.options.some((option) => option.value === value) ? value : null;
    },
    format: (raw, config) =>
      config.selectionMode === 'multiple'
        ? choiceLabels(raw, config.options, SELECT_VALUE_SEPARATOR)
        : choiceLabel(raw, config.options),
  });
}

/**
 * The one descriptor whose renderer edits nothing.
 *
 * `MediaFieldInputComponent` draws a placeholder glyph and has no control on it, so it never emits
 * and `serialize` is only ever handed a value this codec itself produced. Identity both ways is
 * therefore not a shortcut but the only correct choice: a value already stored against a Media
 * field passes through untouched, survives every save, and — because the round trip is exact —
 * is never mistaken for unreadable by `FieldInputComponent.storedValueUnreadable`. Anything
 * narrower would have this renderer quietly erase data it simply cannot display yet.
 */
export function mediaFieldRenderer(
  overrides: Partial<MediaFieldConfig> = {},
): ErasedFieldRendererDescriptor {
  const defaultConfig: MediaFieldConfig = { ...DEFAULT_MEDIA_FIELD_CONFIG, ...overrides };

  return eraseFieldRenderer<'media'>({
    kind: 'media',
    renderer: MediaFieldInputComponent,
    defaultConfig,
    // The one descriptor that opts out. This renderer draws a fixed placeholder glyph and edits
    // nothing, so a preview of it restates the field type rather than reflecting its settings.
    hasPreview: false,
    parse: (json) => parseMediaFieldConfig(json, defaultConfig),
    serialize: (value) => value,
    deserialize: (raw) => raw,
  });
}

export function dateFieldRenderer(
  overrides: Partial<DateFieldConfig> = {},
): ErasedFieldRendererDescriptor {
  const defaultConfig: DateFieldConfig = { ...DEFAULT_DATE_FIELD_CONFIG, ...overrides };

  return eraseFieldRenderer<'date'>({
    kind: 'date',
    renderer: DateFieldInputComponent,
    defaultConfig,
    parse: (json) => parseDateFieldConfig(json, defaultConfig),
    serialize: (value, config) => serializeDateValue(value, config),
    deserialize: (raw, config) => deserializeDateValue(raw, config),
    // The dates as the picker itself writes them — `09/11/2026` for the `2026-09-11` stored above.
    // Every selection mode is covered, since each stores its dates in one string.
    format: (raw, config) => formatDateValue(raw, config),
  });
}

/**
 * A date value as the wire holds it.
 *
 * Always naive and local — never `toISOString()`. See `formatLocalDate` for why: a date-only
 * field picked as the 1st in any negative-offset zone would otherwise store the 31st of the
 * previous month.
 *
 * `selectionMode` decides the shape, which is why the codec needs the config at all. A range
 * keeps its separator even when half-picked, so `2026-01-01/` round-trips rather than collapsing
 * into a single date.
 */
function serializeDateValue(value: DateFieldValue, config: DateFieldConfig): string {
  const format = config.showTime ? formatLocalDateTime : formatLocalDate;

  if (config.selectionMode === 'range') {
    const [start, end] = Array.isArray(value) ? value : [value, null];
    const startText = start instanceof Date ? format(start) : '';
    const endText = end instanceof Date ? format(end) : '';

    return startText === '' && endText === ''
      ? ''
      : `${startText}${DATE_RANGE_SEPARATOR}${endText}`;
  }

  if (config.selectionMode === 'multiple') {
    const dates = Array.isArray(value) ? value : value === null ? [] : [value];

    return dates
      .filter((date): date is Date => date instanceof Date)
      .map((date) => format(date))
      .join(MULTIPLE_DATE_SEPARATOR);
  }

  // 'single'. An array here means the field's mode changed under stored data; the first date is
  // the most useful reading of it.
  const single = Array.isArray(value) ? (value[0] ?? null) : value;

  return single instanceof Date ? format(single) : '';
}

/**
 * A stored number as its config says to read it — grouping, fraction digits, affixes, ISO code.
 *
 * Answers with the raw string untouched for anything it cannot render: a value that is not a
 * number, a fraction-digit pair the platform rejects (`min` above `max`), or an ISO code `Intl`
 * does not know. Nothing here throws, per the rule the value codecs are written to — a stored
 * value this package may not have written must never be able to break a cell.
 */
function formatDecimal(
  raw: string,
  locale: string,
  options: {
    useGrouping: boolean;
    minFractionDigits: number | null;
    maxFractionDigits: number | null;
    prefix?: string;
    suffix?: string;
    currency?: string;
    /** Only meaningful beside `currency`. Omitted leaves `Intl` on its own default, `'symbol'`. */
    currencyDisplay?: string;
  },
): string {
  const value = parseFiniteNumber(raw);

  if (value === null) {
    return raw;
  }

  // `Intl` throws on a min above max rather than clamping, and a config can hold that pair.
  const min = options.minFractionDigits;
  const max =
    options.maxFractionDigits !== null && min !== null && options.maxFractionDigits < min
      ? min
      : options.maxFractionDigits;

  try {
    const formatted = new Intl.NumberFormat(locale === '' ? undefined : locale, {
      useGrouping: options.useGrouping,
      minimumFractionDigits: min ?? undefined,
      maximumFractionDigits: max ?? undefined,
      ...(options.currency === undefined || options.currency === ''
        ? {}
        : {
            style: 'currency' as const,
            currency: options.currency,
            // Carried through so a field set to read as `EUR 1,234.50` does not render as
            // `€1,234.50` here and then change shape the moment its control opens. `Intl`
            // defaults to `'symbol'` when this is absent, which is what made the two disagree.
            ...(options.currencyDisplay === undefined
              ? {}
              : {
                  currencyDisplay: options.currencyDisplay as
                    'symbol' | 'narrowSymbol' | 'code' | 'name',
                }),
          }),
    }).format(value);

    return `${options.prefix ?? ''}${formatted}${options.suffix ?? ''}`;
  } catch {
    return raw;
  }
}

/**
 * A stored date value as the picker draws it, in every selection mode.
 *
 * Each mode keeps its own separator on the way out, so the formatted string has the same shape as
 * the stored one and reads as the same kind of answer — a range still reads as two dates with a
 * `/` between them, not as one run-on string. A part that will not parse is passed through as it
 * was stored rather than dropped, so a half-picked range still reads.
 */
function formatDateValue(raw: string, config: DateFieldConfig): string {
  const options = { showTime: config.showTime, showSeconds: config.showSeconds };

  const one = (part: string): string => {
    const date = parseLocalDateish(part);

    return date === null ? part : formatDateByPattern(date, config.dateFormat, options);
  };

  if (config.selectionMode === 'range') {
    // Split into exactly two, since either end may be empty and both have to survive the trip.
    const [start = '', end = ''] = raw.split(DATE_RANGE_SEPARATOR);

    return `${one(start)}${DATE_RANGE_SEPARATOR}${one(end)}`;
  }

  if (config.selectionMode === 'multiple') {
    return raw
      .split(MULTIPLE_DATE_SEPARATOR)
      .map((part) => part.trim())
      .filter((part) => part !== '')
      .map(one)
      .join(`${MULTIPLE_DATE_SEPARATOR} `);
  }

  return one(raw);
}

/**
 * A stored option value as the label it was authored with.
 *
 * An option since removed falls back to the stored value rather than to an empty string, for the
 * same reason the codecs above never rewrite one: the display form is a reading of what is
 * stored, and answering with nothing would describe the row as blank when it is not.
 */
function choiceLabel(raw: string, options: readonly FieldChoiceOption[]): string {
  const value = raw.trim();

  return options.find((option) => option.value === value)?.label ?? raw;
}

/**
 * The labels of a multi-value stored string, joined for reading.
 *
 * Joined with `', '` rather than with the wire separator on purpose: this string is only ever
 * displayed, never parsed back, and reusing the storage separator would invite a later reader to
 * try splitting on it.
 */
function choiceLabels(
  raw: string,
  options: readonly FieldChoiceOption[],
  separator: string,
): string {
  return raw
    .split(separator)
    .map((part) => part.trim())
    .filter((part) => part !== '')
    .map((part) => choiceLabel(part, options))
    .join(', ');
}

/** The dates a stored value means. Never throws: an unreadable value is null, which
    `FieldInputComponent` reports rather than repairing. */
function deserializeDateValue(raw: string, config: DateFieldConfig): DateFieldValue {
  const value = raw.trim();

  if (value === '') {
    return null;
  }

  if (config.selectionMode === 'range') {
    const [startText = '', endText = ''] = value.split(DATE_RANGE_SEPARATOR);
    const start = parseLocalDateish(startText);
    const end = parseLocalDateish(endText);

    if (start === null && end === null) {
      return null;
    }

    // Both slots, nulls kept: `p-datepicker` reads range mode as a two-slot array and fills the
    // second on the user's next click. Dropping a null end would make the control think the
    // range was complete.
    return [start, end];
  }

  if (config.selectionMode === 'multiple') {
    const dates = value
      .split(MULTIPLE_DATE_SEPARATOR)
      .map((part) => parseLocalDateish(part))
      .filter((date): date is Date => date !== null);

    return dates.length === 0 ? null : dates;
  }

  return parseLocalDateish(value);
}
