import {
  afterRenderEffect,
  ChangeDetectionStrategy,
  Component,
  computed,
  ElementRef,
  inject,
  input,
  model,
  output,
  SecurityContext,
  viewChild,
} from '@angular/core';
import { DomSanitizer } from '@angular/platform-browser';
import { toRichTextHtml } from '../../models/rich-text';

/** The `document.execCommand` names behind the five toolbar buttons. */
type RichTextCommand =
  | 'bold'
  | 'italic'
  | 'underline'
  | 'insertUnorderedList'
  | 'insertOrderedList';

/** One `line-height` of the box, in px — what `rows` is multiplied by. Matches the stylesheet. */
const LINE_HEIGHT_PX = 18;
/** Vertical padding plus border of the box, in px. Matches the stylesheet. */
const BOX_CHROME_PX = 14;

/**
 * The rich-text box a `TextArea` field draws when its config has `wysiwyg` on.
 *
 * A trimmed port of the client's notes composer (`app-wysiwyg-editor`): the same `contenteditable`
 * box and `execCommand` formatting, keeping only its five format buttons — no placeholder,
 * attachments, notify list, mentions or submit button, since a field saves through its host like
 * every other renderer.
 *
 * The icons are inline SVG copied from Lucide rather than `@lucide/angular`, so this package does
 * not take a peer dependency for five glyphs.
 *
 * Not registered on its own: `TextareaFieldInputComponent` draws it in place of its `<textarea>`.
 */
@Component({
  selector: 'vcr-rich-text-editor',
  standalone: true,
  templateUrl: './rich-text-editor.component.html',
  styleUrls: ['./rich-text-editor.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RichTextEditorComponent {
  /** Sanitized HTML. */
  readonly value = model('');
  readonly inputId = input('');
  /** The box's resting height, in lines. It grows past this as content is added. */
  readonly rows = input(5);
  readonly required = input(false);
  readonly disabled = input(false);
  readonly invalid = input(false);
  /** Fires when focus leaves the whole composer — not when it moves between the box and its
      toolbar. */
  readonly blurred = output<void>();

  private readonly sanitizer = inject(DomSanitizer);
  private readonly composer = viewChild.required<ElementRef<HTMLElement>>('composer');
  private readonly editor = viewChild.required<ElementRef<HTMLElement>>('editor');

  readonly minHeight = computed(() => `${this.rows() * LINE_HEIGHT_PX + BOX_CHROME_PX}px`);

  /**
   * The last value this component wrote itself. `innerHTML` is only replaced when `value` arrives
   * as something else, i.e. from the host — rewriting it on every keystroke would throw the caret
   * back to the start of the box.
   */
  private lastEmitted: string | null = null;

  constructor() {
    afterRenderEffect({
      write: () => {
        const value = this.value();

        if (value === this.lastEmitted) {
          return;
        }

        this.editor().nativeElement.innerHTML =
          this.sanitizer.sanitize(SecurityContext.HTML, toRichTextHtml(value)) ?? '';
        this.lastEmitted = value;
      },
    });
  }

  format(command: RichTextCommand): void {
    if (this.disabled()) {
      return;
    }

    this.editor().nativeElement.focus();
    document.execCommand(command);
    // `execCommand` raises `input` in current browsers; reading back here as well covers the ones
    // that do not, and costs nothing when it has already happened.
    this.onInput();
  }

  onInput(): void {
    const html = this.editor().nativeElement.innerHTML;
    const sanitized = this.sanitizer.sanitize(SecurityContext.HTML, html)?.trim() ?? '';
    // An emptied box keeps a stray `<br>` or empty list in Chrome and Safari. Stored as-is it would
    // read as a value, so a field cleared by hand would never be empty again.
    const next = hasText(sanitized) ? sanitized : '';

    if (next === this.value()) {
      return;
    }

    this.lastEmitted = next;
    this.value.set(next);
  }

  onFocusOut(event: FocusEvent): void {
    const next = event.relatedTarget;

    if (next instanceof Node && this.composer().nativeElement.contains(next)) {
      return;
    }

    this.blurred.emit();
  }
}

function hasText(html: string): boolean {
  return (
    html
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .trim().length > 0
  );
}
