import {
  collectExtras,
  FieldConfigExtras,
  readBoolean,
  readConfigSource,
  readNumber,
  readOption,
  readString,
} from './config-readers';
import { ConfigSelectOption } from './field-definition-type-common.model';

/**
 * How many dates one value holds.
 *
 * This is the only config member that changes the *shape* of the value — `'single'` stores one
 * date, `'multiple'` a comma-separated list, `'range'` a `start/end` pair — so changing it on a
 * field that already holds data leaves stored values in a shape the new mode does not read. The
 * config editor warns about that, and `FieldDefinitionDetailComponent` locks `fieldType` on an
 * edit for the same family of reasons.
 */
export const DATE_SELECTION_MODES = ['single', 'multiple', 'range'] as const;

export type DateSelectionMode = (typeof DATE_SELECTION_MODES)[number];

export const DATE_SELECTION_MODE_OPTIONS: ConfigSelectOption<DateSelectionMode>[] = [
  { label: 'Single date', value: 'single' },
  { label: 'Multiple dates', value: 'multiple' },
  { label: 'Date range', value: 'range' },
];

/**
 * The date formats the config editor offers, as PrimeNG tokens.
 *
 * A closed list rather than the free-text box this replaced: every format below reads
 * unambiguously to a user picking one, where a typed token string reads as an invitation to
 * invent `DD-MMM-YY` and discover at render time that PrimeNG spells it differently. A saved
 * config holding a format that is not here still opens with it — see
 * `DateFieldConfigComponent.dateFormatOptions`.
 *
 * PrimeNG's tokens are not Angular's: `MM` is the month's full name, `yy` a 4-digit year.
 */
export const DATE_FORMAT_OPTIONS: ConfigSelectOption<string>[] = [
  { label: 'MM/DD/YYYY', value: 'mm/dd/yy' },
  { label: 'DD/MM/YYYY', value: 'dd/mm/yy' },
  { label: 'Month Day, Year', value: 'MM d, yy' },
  { label: 'Month Year', value: 'MM yy' },
  { label: 'Year', value: 'yy' },
];

/**
 * A limit on the calendar relative to the day it is opened, rather than to a fixed date.
 *
 * The two are the cases a fixed bound cannot express: a date of birth is always in the past and
 * an appointment always ahead, whatever day the form is filled in. Both include today — a field
 * that refuses the current date is a rarer thing to want than one that accepts it, and `minDate`
 * or `maxDate` can still say so. Applied on top of the fixed bounds, never instead of them: see
 * `DateFieldInputComponent.minDate`.
 */
export const DATE_LIMITS = ['none', 'future', 'past'] as const;

export type DateLimit = (typeof DATE_LIMITS)[number];

export const DATE_LIMIT_OPTIONS: ConfigSelectOption<DateLimit>[] = [
  { label: 'No limit', value: 'none' },
  { label: 'Future Dates Only', value: 'future' },
  { label: 'Past Dates Only', value: 'past' },
];

/** Which panel the picker opens on — `'month'` and `'year'` skip straight to those. */
export const DATE_VIEWS = ['date', 'month', 'year'] as const;

export type DateView = (typeof DATE_VIEWS)[number];

export const DATE_VIEW_OPTIONS: ConfigSelectOption<DateView>[] = [
  { label: 'Date', value: 'date' },
  { label: 'Month', value: 'month' },
  { label: 'Year', value: 'year' },
];

export const HOUR_FORMATS = ['12', '24'] as const;

export type HourFormat = (typeof HOUR_FORMATS)[number];

export const HOUR_FORMAT_OPTIONS: ConfigSelectOption<HourFormat>[] = [
  { label: '12 hour', value: '12' },
  { label: '24 hour', value: '24' },
];

/** Whether the calendar icon sits inside the input or as a button beside it. */
export const DATE_ICON_DISPLAYS = ['input', 'button'] as const;

export type DateIconDisplay = (typeof DATE_ICON_DISPLAYS)[number];

export const DATE_ICON_DISPLAY_OPTIONS: ConfigSelectOption<DateIconDisplay>[] = [
  { label: 'Inside the input', value: 'input' },
  { label: 'As a button', value: 'button' },
];

/**
 * What a `DatePicker` field's `fieldConfig` JSON deserialises to.
 *
 * One shape for a date with or without a time: `showTime` is what separates them, which is why
 * the earlier `Date` and `DateTime` field types collapsed into this one. `showTime` also
 * decides the stored format — `2026-09-11` against `2026-09-11T14:30:00` — so it is read by the
 * codec as well as by the control. See `formatLocalDate` for why neither carries a timezone.
 *
 * Read by `DateFieldInputComponent`, written by `DateFieldConfigComponent`.
 */
export interface DateFieldConfig extends FieldConfigExtras {
  /**
   * How the selected date is written in the input.
   *
   * **PrimeNG's tokens, not Angular's `DatePipe` tokens**: `mm/dd/yy` means a 2-digit month, a
   * 2-digit day and a 4-digit year, where `DatePipe` would read `yy` as 2 digits. Display only —
   * it never affects the stored value, which is always ISO-shaped.
   *
   * Typed as a free string rather than a union of {@link DATE_FORMAT_OPTIONS}: the editor offers
   * that list alone, but configs written before it existed hold formats that are not on it and
   * are kept rather than rewritten.
   */
  dateFormat: string;
  /** Also selects the stored format, so changing it on a field with data leaves the old values
      readable but truncated to midnight. */
  showTime: boolean;
  hourFormat: HourFormat;
  showSeconds: boolean;
  /** How many minutes the time spinner moves per step. */
  stepMinute: number;
  showIcon: boolean;
  iconDisplay: DateIconDisplay;
  selectionMode: DateSelectionMode;
  /** Bounds the calendar against the day it is opened — see {@link DATE_LIMITS}. */
  dateLimit: DateLimit;
  /**
   * Whether the fixed bounds below apply at all.
   *
   * Off by default, and the renderer ignores `minDate`/`maxDate` while it is — so the two keep
   * whatever was typed into them and come back unchanged when it is switched on again, the same
   * bargain `TextFieldConfig.prefix` strikes with its mode.
   */
  restrictDateRange: boolean;
  /** `YYYY-MM-DD`, or empty for no bound. Stored as text rather than a `Date` so the config
      round-trips through JSON unchanged; converted to a `Date` at the binding. */
  minDate: string;
  maxDate: string;
  /** How many months the panel shows side by side. Most useful with `selectionMode: 'range'`. */
  numberOfMonths: number;
  /** Show the Today and Clear buttons under the calendar. */
  showButtonBar: boolean;
  showClear: boolean;
  /** Force the date to be chosen from the calendar rather than typed. */
  readonlyInput: boolean;
  /** Draw the calendar always-open, in place, instead of as an overlay. */
  inline: boolean;
  view: DateView;
  placeholder: string;
}

export const DEFAULT_DATE_FIELD_CONFIG: DateFieldConfig = {
  dateFormat: 'mm/dd/yy',
  showTime: false,
  hourFormat: '12',
  showSeconds: false,
  stepMinute: 1,
  showIcon: true,
  iconDisplay: 'input',
  selectionMode: 'single',
  dateLimit: 'none',
  restrictDateRange: false,
  minDate: '',
  maxDate: '',
  numberOfMonths: 1,
  showButtonBar: false,
  showClear: false,
  readonlyInput: false,
  inline: false,
  view: 'date',
  placeholder: '',
  extra: {},
};

/** A saved date config, defaulting every member it cannot read. See `parseTextFieldConfig` for
    why `defaults` is a parameter — it is what lets the retired `DateTime` type still open with
    time switched on. */
export function parseDateFieldConfig(
  json: string | null,
  defaults: DateFieldConfig,
): DateFieldConfig {
  const source = readConfigSource(json);

  if (source === null) {
    return defaults;
  }

  const minDate = readString(source['minDate'], defaults.minDate);
  const maxDate = readString(source['maxDate'], defaults.maxDate);

  return {
    dateFormat: readString(source['dateFormat'], defaults.dateFormat),
    showTime: readBoolean(source['showTime'], defaults.showTime),
    hourFormat: readOption(source['hourFormat'], HOUR_FORMATS, defaults.hourFormat),
    showSeconds: readBoolean(source['showSeconds'], defaults.showSeconds),
    stepMinute: readNumber(source['stepMinute'], defaults.stepMinute),
    showIcon: readBoolean(source['showIcon'], defaults.showIcon),
    iconDisplay: readOption(source['iconDisplay'], DATE_ICON_DISPLAYS, defaults.iconDisplay),
    selectionMode: readOption(
      source['selectionMode'],
      DATE_SELECTION_MODES,
      defaults.selectionMode,
    ),
    dateLimit: readOption(source['dateLimit'], DATE_LIMITS, defaults.dateLimit),
    // A config saved before this member existed has none to read, and defaulting it to off would
    // quietly widen every calendar already limited. So a bound in the saved config is taken as
    // proof the range was meant to apply.
    restrictDateRange: readBoolean(
      source['restrictDateRange'],
      defaults.restrictDateRange || minDate.trim() !== '' || maxDate.trim() !== '',
    ),
    minDate,
    maxDate,
    numberOfMonths: readNumber(source['numberOfMonths'], defaults.numberOfMonths),
    showButtonBar: readBoolean(source['showButtonBar'], defaults.showButtonBar),
    showClear: readBoolean(source['showClear'], defaults.showClear),
    readonlyInput: readBoolean(source['readonlyInput'], defaults.readonlyInput),
    inline: readBoolean(source['inline'], defaults.inline),
    view: readOption(source['view'], DATE_VIEWS, defaults.view),
    placeholder: readString(source['placeholder'], defaults.placeholder),
    extra: collectExtras(source, defaults),
  };
}
