import {
  collectExtras,
  FieldConfigExtras,
  readArray,
  readBoolean,
  readConfigSource,
  readOption,
  readRecord,
  readString,
} from './config-readers';
import {
  CHOICE_ORIENTATIONS,
  CHOICE_SORTS,
  ChoiceOrientation,
  ChoiceSort,
  ConfigSelectOption,
  FieldChoiceOption,
  FieldInputSize,
  normalizeFieldInputSize,
  parseChoiceOptions,
  STORED_FIELD_INPUT_SIZES,
} from './field-definition-type-common.model';

/**
 * Which of the two controls a `Checkbox` field draws.
 *
 * One field type rather than two, because to an author they are the same question asked at
 * different widths — "tick this" and "tick any of these". The cost is that the two modes hold
 * different *shapes* of value, so this member is read by the codec as well as by the control: see
 * `CheckboxFieldValue` and the branching in `checkboxFieldRenderer`.
 */
export const CHECKBOX_TYPES = ['single', 'group'] as const;

export type CheckboxType = (typeof CHECKBOX_TYPES)[number];

export const CHECKBOX_TYPE_OPTIONS: ConfigSelectOption<CheckboxType>[] = [
  { label: 'Single (Default)', value: 'single' },
  { label: 'Group', value: 'group' },
];

/** Which side of the box its caption sits on, in `'single'` mode. */
export const LABEL_POSITIONS = ['right', 'left'] as const;

export type LabelPosition = (typeof LABEL_POSITIONS)[number];

export const LABEL_POSITION_OPTIONS: ConfigSelectOption<LabelPosition>[] = [
  { label: 'After the box', value: 'right' },
  { label: 'Before the box', value: 'left' },
];

/**
 * What separates the ticked values in `'group'` mode.
 *
 * A field value is one string, so a group has to join its selections. The comma matches the date
 * renderer's `'multiple'` mode — and is why `CheckboxFieldConfigComponent` rejects an option value
 * containing one: the join would be unreadable on the way back.
 */
export const CHECKBOX_VALUE_SEPARATOR = ',';

/**
 * What a `Checkbox` field's `fieldConfig` JSON deserialises to.
 *
 * Read by `CheckboxFieldInputComponent`, written by `CheckboxFieldConfigComponent`.
 *
 * **Half of these members belong to one mode and half to the other**, which is unusual here and
 * deliberate: `Checkbox` replaced the earlier `Boolean` and `CheckboxGroup` types, and folding two
 * config shapes into one is what lets an author flip between them without creating a second field.
 * The editor only ever shows the half that applies, and {@link CheckboxType} says which.
 */
export interface CheckboxFieldConfig extends FieldConfigExtras {
  checkboxType: CheckboxType;

  // --- `'single'` only ------------------------------------------------------------------------
  /** The caption beside the box. PrimeNG's `p-checkbox` has no `label` input, so this is drawn
      by the renderer's own markup. Empty draws none, leaving the field's own label to do the
      work. */
  label: string;
  labelPosition: LabelPosition;
  /**
   * Offer "not set" as a third state, cycling unset → checked → unchecked.
   *
   * Worth having when the field is not required: a plain checkbox cannot express "nobody has
   * answered", so an untouched field and a deliberate "no" look identical both here and in the
   * stored data.
   */
  triState: boolean;
  /** What a checked box stores. */
  trueText: string;
  /** What an unchecked box stores. */
  falseText: string;
  /** Draw the box but refuse interaction, for a value shown as context rather than edited. */
  readonly: boolean;
  /** A PrimeIcons class overriding the tick (e.g. `pi pi-times`). Empty keeps the default. */
  checkboxIcon: string;

  // --- `'group'` only -------------------------------------------------------------------------
  /** The boxes the field offers. Empty renders nothing selectable, which is why
      `CheckboxFieldConfigComponent.isValid` requires at least one in this mode. */
  options: FieldChoiceOption[];
  orientation: ChoiceOrientation;
  /** What order the boxes are drawn in — see {@link sortChoiceOptions}. Applied at render time,
      so `options` above stays in the order it was authored. */
  sortChoices: ChoiceSort;
  /**
   * How many boxes must be ticked for the field to be complete, and how many may be. `0` on
   * either means "no bound".
   *
   * Advisory, not enforced on save: the backend types a field value as a free string and this app
   * cannot make it reject one. The renderer marks itself invalid, which is what a consuming site
   * would act on.
   */
  minSelected: number;
  maxSelected: number;
  /** Draw a "Select all" box above the options, ticking or clearing every one of them at once. */
  showToggleAll: boolean;

  // --- both -----------------------------------------------------------------------------------
  size: FieldInputSize;
}

export const DEFAULT_CHECKBOX_FIELD_CONFIG: CheckboxFieldConfig = {
  checkboxType: 'single',
  label: '',
  labelPosition: 'right',
  triState: false,
  trueText: 'true',
  falseText: 'false',
  readonly: false,
  checkboxIcon: '',
  options: [],
  orientation: 'vertical',
  sortChoices: 'none',
  minSelected: 0,
  maxSelected: 0,
  showToggleAll: false,
  size: 'small',
  extra: {},
};

/**
 * The members belonging to whichever mode is *not* active, back at their defaults.
 *
 * Used by the editor when the author switches mode: the settings of the mode being left behind
 * are cleared rather than carried, so a group cannot be saved holding a stale `trueText` and a
 * single box cannot be saved holding options nothing renders.
 */
export function clearedCheckboxModeSettings(
  checkboxType: CheckboxType,
): Partial<CheckboxFieldConfig> {
  const {
    label,
    labelPosition,
    triState,
    trueText,
    falseText,
    readonly,
    checkboxIcon,
    options,
    orientation,
    sortChoices,
    minSelected,
    maxSelected,
    showToggleAll,
  } = DEFAULT_CHECKBOX_FIELD_CONFIG;

  return checkboxType === 'group'
    ? { options, orientation, sortChoices, minSelected, maxSelected, showToggleAll }
    : { label, labelPosition, triState, trueText, falseText, readonly, checkboxIcon };
}

/** A saved checkbox config, defaulting every member it cannot read. */
export function parseCheckboxFieldConfig(
  json: string | null,
  defaults: CheckboxFieldConfig,
): CheckboxFieldConfig {
  const source = readConfigSource(json);

  if (source === null) {
    return defaults;
  }

  return {
    checkboxType: readOption(source['checkboxType'], CHECKBOX_TYPES, defaults.checkboxType),
    label: readString(source['label'], defaults.label),
    labelPosition: readOption(source['labelPosition'], LABEL_POSITIONS, defaults.labelPosition),
    triState: readBoolean(source['triState'], defaults.triState),
    trueText: readString(source['trueText'], defaults.trueText),
    falseText: readString(source['falseText'], defaults.falseText),
    readonly: readBoolean(source['readonly'], defaults.readonly),
    checkboxIcon: readString(source['checkboxIcon'], defaults.checkboxIcon),
    options: parseChoiceOptions(
      readArray(source['options']),
      defaults.options,
      readString,
      readRecord,
    ),
    orientation: readOption(source['orientation'], CHOICE_ORIENTATIONS, defaults.orientation),
    sortChoices: readOption(source['sortChoices'], CHOICE_SORTS, defaults.sortChoices),
    minSelected: readCount(source['minSelected'], defaults.minSelected),
    maxSelected: readCount(source['maxSelected'], defaults.maxSelected),
    showToggleAll: readBoolean(source['showToggleAll'], defaults.showToggleAll),
    size: normalizeFieldInputSize(
      readOption(source['size'], STORED_FIELD_INPUT_SIZES, defaults.size),
    ),
    extra: collectExtras(source, defaults),
  };
}

/** A whole count of zero or more, or the default. A negative or fractional bound is not a bound
    anyone meant, and letting one through would mark every value invalid with no way to see why. */
function readCount(raw: unknown, fallback: number): number {
  return typeof raw === 'number' && Number.isInteger(raw) && raw >= 0 ? raw : fallback;
}
